inline void SimStateReset( SimState & value )
{
    value.tilt = 0;
    value.angle = 0;
    value.position = 0;
    value.reach = 0;
    value.ticks = 0;
    value.ratio = 0;
    value.speed = 0;
    value.span = 0;
    value.mass = 0;
    value.frames = 0;
    value.flux = 0;
    value.energy = serialize::int128_t( ( serialize::uint128_t( 18446744073709551615ull ) << 64 ) | serialize::uint128_t( 18446744073709551366ull ) );
    value.entity_id = 0;
    value.scale = 65536;
    memset( value.samples, 0, sizeof( value.samples ) );
    memset( value.weights, 0, sizeof( value.weights ) );
    value.weights_count = 0;
    memset( value.axes.slots, 0, sizeof( value.axes.slots ) );
    memset( value.seeds, 0, sizeof( value.seeds ) );
    value.seeds_count = 0;
    PoseReset( value.pose );
    PoseReset( value.spawn );
    value.spawn_present = false;
}

inline void PoseReset( Pose & value ) { value = Pose(); }

